			p := palette("Go to", "zz", nil, r)
			p.List.Notice = "Unknown command: zz"
			return p
		}(), theme.IconWarning + " Unknown command: zz", ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			lines := plain(renderPalette(t, tt.p, r))
