		for name, p := range map[string]PaletteInput{
			"all":    palette("Go to", "", allRows(), r),
			"cursor": func() PaletteInput { p := palette("Go to", "", allRows(), r); p.List.Cursor = 2; return p }(),
			"notice": func() PaletteInput {
				p := palette("Go to", "x", nil, r)
